from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost_probation = OrderedDict()
        self.ghost_protected = OrderedDict()
        self.protected_target = (self.capacity_bytes * 3) // 5
        self.used_bytes = 0
        self.events = 0
        self.history_limit = max(256, min(16384, self.capacity_bytes // 64 + 256))
        self.ghost_limit = max(64, min(8192, self.capacity_bytes // 64 + 64))
        self.history = OrderedDict()

    def _touch_history(self, key):
        count = self.history.pop(key, 0)
        self.history[key] = min(255, count + 1)
        self.events += 1
        if self.events % 2048 == 0:
            for old_key in list(self.history):
                value = self.history[old_key] // 2
                if value:
                    self.history[old_key] = value
                else:
                    del self.history[old_key]
        while len(self.history) > self.history_limit:
            self.history.popitem(last=False)

    def _score(self, key):
        return max(1, self.history.get(key, 1))

    def _remember(self, ghost, key):
        ghost.pop(key, None)
        ghost[key] = None
        while len(ghost) > self.ghost_limit:
            ghost.popitem(last=False)

    def _forget_ghost(self, key):
        self.ghost_probation.pop(key, None)
        self.ghost_protected.pop(key, None)

    def _rebalance(self):
        protected_bytes = sum(self.protected.values())
        while self.protected and protected_bytes > self.protected_target:
            old_key, old_size = self.protected.popitem(last=False)
            self.probation[old_key] = old_size
            protected_bytes -= old_size

    def _evict_one(self, avoid=None):
        for cache, ghost in (
            (self.probation, self.ghost_probation),
            (self.protected, self.ghost_protected),
        ):
            old_key = next((candidate for candidate in cache if candidate != avoid), None)
            if old_key is None:
                continue
            old_size = cache.pop(old_key)
            self._remember(ghost, old_key)
            self.used_bytes -= old_size
            return old_key
        return None

    def _remove_resident(self, key):
        for cache, ghost in (
            (self.probation, self.ghost_probation),
            (self.protected, self.ghost_protected),
        ):
            if key in cache:
                size = cache.pop(key)
                self.used_bytes -= size
                self._remember(ghost, key)
                return size
        return None

    def _can_admit(self, size, candidate_score, ghosted):
        required = self.used_bytes + size - self.capacity_bytes
        if required <= 0:
            return True
        freed = 0
        for cache in (self.probation, self.protected):
            for victim, victim_size in cache.items():
                victim_score = self._score(victim)
                if candidate_score < victim_score or (
                    candidate_score == victim_score and not ghosted
                ):
                    return False
                freed += victim_size
                if freed >= required:
                    return True
        return False

    def _resize_existing(self, key, size, cache):
        old_size = cache[key]
        if size <= 0 or size > self.capacity_bytes:
            self._remove_resident(key)
            return [key]
        delta = size - old_size
        evicted = []
        while delta > 0 and self.used_bytes + delta > self.capacity_bytes:
            victim = self._evict_one(avoid=key)
            if victim is None:
                self._remove_resident(key)
                return evicted + [key]
            evicted.append(victim)
        cache[key] = size
        self.used_bytes += delta
        return evicted

    def access(self, key: int, size: int, now: int) -> list[int]:
        self._touch_history(key)

        if key in self.protected:
            stored_size = self.protected.pop(key)
            self.protected[key] = stored_size
            return self._resize_existing(key, size, self.protected)

        if key in self.probation:
            stored_size = self.probation.pop(key)
            self.protected[key] = stored_size
            evicted = self._resize_existing(key, size, self.protected)
            if key in self.protected:
                self._rebalance()
            return evicted

        if self.capacity_bytes == 0 or size <= 0 or size > self.capacity_bytes:
            return []

        ghosted = key in self.ghost_probation or key in self.ghost_protected
        candidate_score = self._score(key)
        if not self._can_admit(size, candidate_score, ghosted):
            return []

        step = max(1, self.capacity_bytes // 16)
        if key in self.ghost_probation:
            self.protected_target = min(
                self.capacity_bytes,
                self.protected_target + max(step, min(size, self.capacity_bytes)),
            )
        elif key in self.ghost_protected:
            self.protected_target = max(
                0,
                self.protected_target - max(step, min(size, self.capacity_bytes)),
            )
        self._forget_ghost(key)

        evicted = []
        while self.used_bytes + size > self.capacity_bytes:
            victim = self._evict_one()
            if victim is None:
                return evicted
            evicted.append(victim)

        self.probation[key] = size
        self.used_bytes += size
        self._rebalance()
        return evicted
